import {useCallback,useEffect,useMemo,useRef,useState} from 'react';import {classifyLead,recommendedAction,SERVICES,type Service} from '@/lib/commercial';import {Activity,ArrowDownToLine,Building2,CalendarDays,Flame,MapPin,Newspaper,Search,ShieldCheck,SlidersHorizontal,Target,TriangleAlert,Wifi,RefreshCw,Bookmark,Check,ChevronDown,ExternalLink,FileSearch,Upload,Download,Trash2,FileSpreadsheet} from 'lucide-react';
type Item={id:string;title:string;buyer:string;city?:string;state?:string;searchEvidence?:string[];matchedTerms?:string[];searchRelevance?:number;sizeCategory?:'small'|'medium'|'large'|'unknown';evidenceClass?:'A'|'B'|'C'|'D';evidenceClasses?:('A'|'B'|'C'|'D')[];description?:string;address?:string;sourceRecords?:{source:string;id:string;url:string}[];origins?:string[];municipalityCode?:number;latitude?:number;longitude?:number;confidence?:string;amount:number|null;published:string|null;filterDate?:string;deadline?:string|null;url:string;origin:string;status?:string;score?:number;evidence?:string[];type?:string;supplier?:string;supplierCnpj?:string;processNumber?:string;recordNumber?:string;signedAt?:string|null;vigencyStart?:string|null;vigencyEnd?:string|null};type News={title:string;url:string;domain:string;published:string|null;potential:string;origin:string};type Saved=Item & {savedAt:string};const PIPELINE_STAGES=['Identificada','Em investigação','Aguardando verificação','Qualificada','Contato planejado','Contatada','Em negociação','Convertida','Descartada'] as const;type PipelineStage=typeof PIPELINE_STAGES[number];type LeadState={stage:PipelineStage;notes:string;nextAction:string;updatedAt:string};type Preferences={region:string;segments:string[];services:string[]};
const localYMD=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const today=localYMD(new Date());const currency=(n:number|null)=>n==null?'Não informado':new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n);const date=(s:string|null|undefined)=>s?new Date(s).toLocaleDateString('pt-BR'):'—';
const categoryTerms:Record<string,string[]>={'Proteção contra incêndio':['incendio','proteção contra incêndio','extintor','hidrante','alarme de incendio'],'Sprinklers':['sprinkler','chuveiro automatico'],'Tubulações e conexões':['tubulação','tubo','conexao'],'Engenharia e instalações':['engenharia','instalação','instalacao'],'Manutenção predial':['manutenção predial','manutencao predial'],'Construção civil':['construção','construcao','obra','reforma'],'Infraestrutura':['infraestrutura','pavimentação','pavimentacao'],'Serviços técnicos':['serviço técnico','servico tecnico','laudo'],'Materiais e equipamentos':['material','equipamento']};function inCategory(item:Item,category:string){const norm=(s:string)=>s.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLocaleLowerCase('pt-BR');const text=norm(`${item.title} ${item.buyer}`);const matches=(categoryTerms[category]||[]).some(t=>text.includes(norm(t)));if(category==='Todas')return true;if(category==='Outros')return !Object.keys(categoryTerms).some(c=>(categoryTerms[c]||[]).some(t=>text.includes(norm(t))));return matches}
export default function Home(){const[tab,setTab]=useState('Oportunidades');const[q,setQ]=useState('');const[uf,setUf]=useState('');const[period,setPeriod]=useState('30');const[from,setFrom]=useState(localYMD(new Date(Date.now()-30*864e5)));const[to,setTo]=useState(today);const[category,setCategory]=useState('Todas');const[serviceFilter,setServiceFilter]=useState<Service|'Todas'>('Todas');const[sort,setSort]=useState('newest');const[source,setSource]=useState('Todas');const[page,setPage]=useState(1);const[size,setSize]=useState(20);const[searchMode,setSearchMode]=useState<'quick'|'expanded'|'detailed'>('quick');const[searchBatch,setSearchBatch]=useState(0);const[moreAvailable,setMoreAvailable]=useState(false);const[data,setData]=useState<Item[]>([]);const[total,setTotal]=useState(0);const[totalPages,setTotalPages]=useState(0);const[sources,setSources]=useState<any[]>([]);const[coverageData,setCoverageData]=useState<any>(null);const[municipalities,setMunicipalities]=useState<{code:number;name:string;uf:string}[]>([]);const[loading,setLoading]=useState(false);const[error,setError]=useState('');const[updated,setUpdated]=useState('');const[saved,setSaved]=useState<Saved[]>([]);const[company,setCompany]=useState('');const[companyData,setCompanyData]=useState<NormalizedCompany|null>(null);const[companyError,setCompanyError]=useState('');const[companyLoading,setCompanyLoading]=useState(false);const[companySources,setCompanySources]=useState<{name:string;status:string;message:string;durationMs?:number;observedAt?:string}[]>([]);const[companyHistory,setCompanyHistory]=useState<{cnpj:string;name:string;checkedAt:string;status:string}[]>([]);const[news,setNews]=useState<News[]>([]);const[newsError,setNewsError]=useState('');const[newsQuery,setNewsQuery]=useState('');const[priceCode,setPriceCode]=useState('');const[priceType,setPriceType]=useState('material');const[prices,setPrices]=useState<any[]>([]);const[priceError,setPriceError]=useState('');const[showInfo,setShowInfo]=useState(false);const[preferences,setPreferences]=useState<Preferences>({region:'',segments:[],services:[...SERVICES]});const[leadStates,setLeadStates]=useState<Record<string,LeadState>>({});const[cityQuery,setCityQuery]=useState('');const[osmCategory,setOsmCategory]=useState('all');const[evidenceFilter,setEvidenceFilter]=useState('Todas');const fileRef=useRef<HTMLInputElement>(null);const abortRef=useRef<AbortController|null>(null);const kind=tab==='Contratos'?'contracts':tab==='Atas'?'atas':'opportunities';
useEffect(()=>{try{const v=JSON.parse(localStorage.getItem('accert:favorites:v2')||'[]');if(Array.isArray(v))setSaved(v.filter(x=>x&&typeof x.id==='string'&&typeof x.title==='string'));const p=JSON.parse(localStorage.getItem('accert:preferences:v1')||'null');if(p)setPreferences({region:String(p.region||''),segments:Array.isArray(p.segments)?p.segments.filter((x:any)=>typeof x==='string'):[],services:Array.isArray(p.services)?p.services.filter((x:any)=>SERVICES.includes(x)): [...SERVICES]});const s=JSON.parse(localStorage.getItem('accert:lead-state:v1')||'{}');if(s&&typeof s==='object'){const migrated:Record<string,LeadState>={};for(const [k,v] of Object.entries(s)){if(typeof v==='string'){const stage:PipelineStage=v==='Contatada'?'Contatada':v==='Verificada'?'Aguardando verificação':'Em investigação';migrated[k]={stage,notes:'',nextAction:'',updatedAt:new Date().toISOString()}}else if(v&&typeof v==='object'&&'stage'in v&&PIPELINE_STAGES.includes((v as LeadState).stage))migrated[k]=v as LeadState}setLeadStates(migrated)}}catch{setSaved([])}},[]);
useEffect(()=>{const query=cityQuery.trim();if(!uf||query.length<2){setMunicipalities([]);return}const controller=new AbortController(),timer=setTimeout(async()=>{try{const response=await fetch('/api/municipalities?'+new URLSearchParams({uf,q:query}),{signal:controller.signal});const body=await response.json();setMunicipalities(body.municipalities||[])}catch{setMunicipalities([])}},350);return()=>{clearTimeout(timer);controller.abort()}},[cityQuery,uf]);const load=useCallback(async(p=page,requestedSize=size,requestedBatch=searchBatch,fromDate=from,toDate=to)=>{if(['Notícias','Salvos','Empresas','Compras.gov.br'].includes(tab))return;abortRef.current?.abort();const c=new AbortController();abortRef.current=c;setLoading(true);setError('');try{const isResearch=kind==='opportunities';const params=new URLSearchParams({page:String(p),size:String(requestedSize),from:fromDate,to:toDate});if(isResearch){params.set('mode',searchMode);params.set('batch',String(requestedBatch));if(q)params.set('q',q);if(cityQuery)params.set('city',cityQuery);const selected:Record<string,string>={'Todas':'all','PNCP':'pncp','Obrasgov.br':'obrasgov','Transferegov.br · Parcerias':'transferegov','GDELT':'gdelt','OpenStreetMap':'osm'};params.set('sources',selected[source]||'all');params.set('osmCategory',osmCategory)}else{params.set('kind',kind);if(q)params.set('q',q)}if(uf)params.set('uf',uf);const r=await fetch((isResearch?'/api/research?':'/api/opportunities?')+params,{signal:c.signal});const j=await r.json();if(!r.ok)throw Error(j.error||'Consulta falhou');setData(j.results||[]);setTotal(j.total||0);setTotalPages(j.totalPages||0);setMoreAvailable(Boolean(j.hasMore));setSearchBatch(requestedBatch);setSources(Array.isArray(j.sources)?j.sources:[{name:'PNCP',status:j.sourceStatus,detail:j.message}]);setCoverageData(j.coverage||null);setUpdated(j.updatedAt);setPage(p)}catch(e:any){if(e.name!=='AbortError'){setError(e.message||'Erro ao carregar');setData([])}}finally{if(!c.signal.aborted)setLoading(false)}},[page,size,searchBatch,searchMode,tab,kind,q,uf,from,to,source,cityQuery,osmCategory]);useEffect(()=>{if(!['Notícias','Salvos','Empresas','Compras.gov.br'].includes(tab))load(1);return()=>abortRef.current?.abort()},[tab]);
function runSearch(){const natural=q.match(/(?:(?:nos?|nas?)\s+)?(?:ultimos?|ultimas?)\s+(\d+)\s+dias?/i);let nextFrom=from,nextTo=to;if(natural){const days=Number(natural[1]);if(days<1||days>90){setError('A busca por período em linguagem natural aceita de 1 a 90 dias.');return}nextFrom=localYMD(new Date(Date.now()-days*864e5));nextTo=today;setFrom(nextFrom);setTo(nextTo)}setSearchBatch(0);load(1,size,0,nextFrom,nextTo)}async function doNews(){setNewsError('');setLoading(true);try{const r=await fetch('/api/news?'+new URLSearchParams({q:newsQuery,days:String(Math.min(90,Math.round((Date.now()-new Date(from).getTime())/864e5)||30))}));const j=await r.json();if(!r.ok)throw Error(j.error);if(j.sourceStatus!=='ok')throw Error(j.message||'GDELT indisponível');setNews(j.articles||[]);setUpdated(j.updatedAt)}catch(e:any){setNewsError(e.message||'Consulta de notícias falhou');setNews([])}finally{setLoading(false)}}
async function lookupCompany(refresh=false){setCompanyError('');setCompanyData(null);setCompanyLoading(true);try{const params=new URLSearchParams({cnpj:company});if(refresh)params.set('refresh','1');const r=await fetch('/api/company?'+params);const j=await r.json();setCompanySources(j.sources||[]);if(!r.ok)throw Error(j.error||'Não foi possível consultar.');setCompanyData(j.company||null);const entry={cnpj:j.company?.cnpj||company.replace(/[^0-9a-z]/gi,'').toUpperCase(),name:j.company?.legalName||'Cadastro não retornado pela fonte',checkedAt:new Date().toISOString(),status:j.queryStatus};setCompanyHistory(prev=>[entry,...prev.filter(x=>x.cnpj!==entry.cnpj)].slice(0,20));if(j.queryStatus==='not_found_in_source')setCompanyError('A fonte consultada não retornou este CNPJ. Isso não permite concluir que a empresa não exista.')}catch(e:any){setCompanyError(e.message||'Não foi possível consultar.');setCompanyHistory(prev=>[{cnpj:company.replace(/[^0-9a-z]/gi,'').toUpperCase(),name:'Consulta sem resultado',checkedAt:new Date().toISOString(),status:'unavailable'},...prev].slice(0,20))}finally{setCompanyLoading(false)}}async function lookupPrices(){setPriceError('');try{const r=await fetch('/api/compras?'+new URLSearchParams({code:priceCode,type:priceType,page:'1',size:'20',from,to}));const j=await r.json();if(!r.ok)throw Error(j.error);setPrices(j.results||[])}catch(e:any){setPriceError(e.message||'Erro ao consultar preços');setPrices([])}}
function persist(items:Saved[]){setSaved(items);try{localStorage.setItem('accert:favorites:v2',JSON.stringify(items))}catch{alert('Não foi possível gravar favoritos neste navegador.')}}function toggleSave(item:Item){const found=saved.some(x=>x.id===item.id&&x.origin===item.origin);persist(found?saved.filter(x=>!(x.id===item.id&&x.origin===item.origin)):[...saved,{...item,savedAt:new Date().toISOString()}])}function exportFavorites(){const blob=new Blob([JSON.stringify({format:'accert-local-workspace-v1',exportedAt:new Date().toISOString(),favorites:saved,pipeline:leadStates,preferences},null,2)],{type:'application/json'});download(blob,'accert-favoritos.json')}function download(blob:Blob,name:string){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}async function importFavorites(file?:File){if(!file)return;if(file.size>1_000_000){alert('Arquivo excede 1 MB.');return}try{const j=JSON.parse(await file.text());const list=Array.isArray(j)?j:j.favorites;if(!Array.isArray(list))throw Error('Formato sem lista favorites');const valid=list.filter((x:any)=>x&&typeof x.id==='string'&&typeof x.title==='string'&&typeof x.origin==='string'&&typeof x.url==='string'&&/^https?:\/\//.test(x.url));const map=new Map(saved.map(x=>[`${x.origin}:${x.id}`,x]));for(const x of valid)map.set(`${x.origin}:${x.id}`,{...x,savedAt:x.savedAt||new Date().toISOString()});persist([...map.values()]);let stagesImported=0;if(j.pipeline&&typeof j.pipeline==='object'&&!Array.isArray(j.pipeline)){const merged={...leadStates};for(const [key,value] of Object.entries(j.pipeline).slice(0,500)){if(value&&typeof value==='object'&&'stage'in value&&PIPELINE_STAGES.includes((value as LeadState).stage)){const v=value as LeadState;merged[key]={stage:v.stage,notes:String(v.notes||'').slice(0,1000),nextAction:String(v.nextAction||'').slice(0,250),updatedAt:String(v.updatedAt||new Date().toISOString())};stagesImported++}}setLeadStates(merged);localStorage.setItem('accert:lead-state:v1',JSON.stringify(merged))}alert(`${valid.length} favorito(s) e ${stagesImported} etapa(s) de prospecção importado(s)/mesclado(s).`)}catch{alert('JSON inválido ou estrutura não reconhecida. Nada foi executado.') }finally{if(fileRef.current)fileRef.current.value=''}}
function updatePreferences(next:Preferences){setPreferences(next);try{localStorage.setItem('accert:preferences:v1',JSON.stringify(next))}catch{}}function markLead(item:Item,patch:Partial<LeadState>){const key=`${item.origin}:${item.id}`,current=leadStates[key]||{stage:'Identificada' as PipelineStage,notes:'',nextAction:'',updatedAt:new Date().toISOString()};const next={...leadStates,[key]:{...current,...patch,updatedAt:new Date().toISOString()}};setLeadStates(next);try{localStorage.setItem('accert:lead-state:v1',JSON.stringify(next))}catch{}}function leadState(item:Item):LeadState{return leadStates[`${item.origin}:${item.id}`]||{stage:'Identificada',notes:'',nextAction:'',updatedAt:''}}function outreach(item:Item){const lead=classifyLead(item);const context=item.title.length>170?item.title.slice(0,167)+'…':item.title;const service=lead.services[0]||'soluções de segurança contra incêndio';return `Olá, somos a Accert Engenharia e atuamos com ${service.toLowerCase()}. Vimos a informação pública sobre “${context}” relacionada a ${item.buyer||'sua organização'} (${item.origin}, ${date(item.published)}). Não estamos presumindo uma necessidade ou irregularidade; gostaríamos de entender a fase do empreendimento e avaliar se podemos apoiar em ${service.toLowerCase()}. Podemos conversar?`};function exportJSON(){download(new Blob([JSON.stringify({format:'accert-opportunities-v1',exportedAt:new Date().toISOString(),opportunities:filtered.map(item=>({...item,commercial:classifyLead(item),leadStatus:leadState(item)}))},null,2)],{type:'application/json'}),'accert-oportunidades.json')}function exportCSV(){const rows=[['Título','Órgão/empresa','Local','Porte','Segmento estimado','Serviços potenciais','Classe de descoberta A-D','Nível de evidência comercial','Confiança/limite da fonte','Prioridade estimada','Estado local','Data','Fontes originais','URL'],...filtered.map((x:any)=>{const c=classifyLead(x,preferences.region);return [x.title,x.buyer||x.domain||'',x.city||x.state||'',x.sizeCategory&&x.sizeCategory!=='unknown'?x.sizeCategory:'não informado',c.segment,c.services.join(', '),x.evidenceClass||x.evidenceClasses?.join(', ')||'não classificada',c.level,x.confidence||c.evidenceConfidence,String(c.priority),leadState(x).stage,date(x.published),(x.sourceRecords||[]).map((s:any)=>`${s.source}:${s.id}`).join(' | ')||x.origin,x.url]})];download(new Blob(['\ufeff'+toSemicolonCsv(rows)],{type:'text/csv;charset=utf-8'}),'accert-resultados.csv')}
const filtered=useMemo(()=>{let list=[...data];if(source!=='Todas')list=list.filter(x=>x.origin===source);list=list.filter(x=>inCategory(x,category));const lo=Date.parse(from+'T00:00:00'),hi=Date.parse(to+'T23:59:59');list=list.filter(x=>{if(x.type==='ata')return true;const dt=Date.parse(x.filterDate||x.published||'');return !Number.isFinite(dt)||(dt>=lo&&dt<=hi)});if(cityQuery)list=list.filter(x=>`${x.city||''} ${x.state||''}`.toLocaleLowerCase('pt-BR').includes(cityQuery.toLocaleLowerCase('pt-BR')));if(preferences.region)list=list.filter(x=>`${x.city||''} ${x.state||''}`.toLocaleLowerCase('pt-BR').includes(preferences.region.toLocaleLowerCase('pt-BR')));if(evidenceFilter!=='Todas')list=list.filter(x=>['A','B','C','D'].includes(evidenceFilter)?(x.evidenceClass===evidenceFilter||x.evidenceClasses?.includes(evidenceFilter as 'A'|'B'|'C'|'D')):classifyLead(x).level===evidenceFilter);if(preferences.segments.length)list=list.filter(x=>preferences.segments.includes(classifyLead(x).segment));list=list.filter(x=>classifyLead(x).services.some(s=>preferences.services.includes(s)));if(serviceFilter!=='Todas')list=list.filter(x=>classifyLead(x).services.includes(serviceFilter));list.sort((a,b)=>{if(sort==='priority')return classifyLead(b,preferences.region).priority-classifyLead(a,preferences.region).priority;const d=Date.parse(a.published||'')-Date.parse(b.published||'');return sort==='newest'?-d:d});return list},[data,source,category,sort,from,to,cityQuery,evidenceFilter,preferences,serviceFilter]);const newsSorted=[...news].sort((a,b)=>{const d=Date.parse(a.published||'')-Date.parse(b.published||'');return sort==='newest'?-d:d});
const nav=['Oportunidades','Território','Contratos','Atas','Notícias','Compras.gov.br','Empresas','Salvos','Fontes e cobertura'];function setPeriodValue(v:string){setPeriod(v);if(v==='custom')return;const days=v==='today'?0:Number(v);setFrom(localYMD(new Date(Date.now()-days*864e5)));setTo(today);setPage(1)}function clearFilters(){setQ('');setUf('');setCategory('Todas');setServiceFilter('Todas');setSource('Todas');setCityQuery('');setEvidenceFilter('Todas');setPeriodValue('30');setSort('newest')}
return <div className="min-h-screen lg:flex"><aside className="hidden lg:flex w-[248px] bg-[#102f34] text-white flex-col px-5 py-7 min-h-screen fixed"><div className="flex items-center gap-3 mb-12"><div className="w-10 h-10 rounded-xl bg-[#c8f36b] text-[#102f34] grid place-items-center"><Flame size={22}/></div><div><div className="font-bold tracking-wide">ACCERT</div><div className="text-[10px] tracking-[.22em] text-[#a6c2c0]">INTELLIGENCE</div></div></div><div className="text-[10px] uppercase tracking-[.16em] text-[#86a4a2] mb-3 px-3">Radar comercial</div>{nav.map(n=><button key={n} onClick={()=>{setTab(n);setPage(1);if(n==='Território')setSource('OpenStreetMap')}} className={`flex gap-3 items-center px-3 py-3 rounded-xl text-sm mb-1 text-left ${tab===n?'bg-[#24474b] text-[#d1f786]':'text-[#c1d1d0] hover:bg-[#1a3d41]'}`}><span className="w-4">{n==='Oportunidades'?<Target size={16}/>:n==='Notícias'?<Newspaper size={16}/>:n==='Empresas'?<Building2 size={16}/>:n==='Salvos'?<Bookmark size={16}/>:n==='Compras.gov.br'?<FileSpreadsheet size={16}/>:n==='Fontes e cobertura'?<Wifi size={16}/>:n==='Território'?<MapPin size={16}/>:<CalendarDays size={16}/>}</span>{n}{n==='Salvos'&&saved.length>0&&<span className="ml-auto text-xs">{saved.length}</span>}</button>)}<div className="mt-auto border-t border-white/10 pt-5 text-xs text-[#9cb5b3] flex gap-2"><ShieldCheck size={15}/> Dados públicos · sem cadastro</div></aside><main className="lg:ml-[248px] flex-1 min-w-0"><header className="bg-white border-b border-[#e5ebea] px-5 sm:px-9 py-4 flex items-center justify-between"><div className="lg:hidden flex items-center gap-2 font-bold"><Flame className="text-[#254749]"/> ACCERT <span className="text-xs font-normal text-slate-500">INTELLIGENCE</span></div><div className="hidden lg:block text-xs text-slate-500">INTELIGÊNCIA COMERCIAL <span className="mx-2">/</span><b className="text-[#24474b]">{tab.toUpperCase()}</b></div><div className="flex items-center gap-3"><span className="hidden sm:flex items-center gap-2 text-xs text-[#667b7c]"><span className="w-2 h-2 bg-green-500 rounded-full"/> Fontes públicas</span><button onClick={()=>tab==='Notícias'?doNews():load(1)} className="p-2 rounded-lg hover:bg-slate-100" title="Atualizar"><RefreshCw size={17} className={loading?'animate-spin':''}/></button></div></header><div className="lg:hidden bg-[#102f34] flex overflow-x-auto px-3 py-2 gap-2">{nav.map(n=><button key={n} onClick={()=>{setTab(n);if(n==='Território')setSource('OpenStreetMap')}} className={`text-xs px-3 py-2 rounded-lg whitespace-nowrap ${tab===n?'bg-white/15 text-[#d1f786]':'text-white/70'}`}>{n}</button>)}</div><div className="max-w-[1440px] mx-auto px-5 sm:px-9 py-7"><div className="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-7"><div><div className="inline-flex items-center gap-2 text-[11px] text-[#54706f] bg-[#e7efeb] rounded-full px-3 py-1.5 mb-3"><Activity size={13}/> RADAR DE MERCADO · BRASIL</div><h1 className="text-3xl sm:text-[34px] font-semibold tracking-tight text-[#18393c]">{tab==='Oportunidades'?'Oportunidades comerciais':tab}</h1><p className="text-sm text-slate-500 mt-2">Sinais públicos para engenharia e proteção contra incêndio.</p></div><button onClick={()=>setShowInfo(!showInfo)} className="text-xs flex items-center gap-2 text-[#56706f] border bg-white px-3 py-2.5 rounded-lg"><ShieldCheck size={15}/> Como funciona</button></div>{showInfo&&<div className="bg-[#eef5e5] border border-[#d7e9bb] p-4 rounded-xl mb-5 text-sm">Prioridade/relevância são classificações heurísticas. Notícias são indícios, não prova de oportunidade. Favoritos só ficam neste navegador; transfira com exportar/importar JSON.</div>}
{tab==='Fontes e cobertura'&&<SourcesPanel status={sources}/>}{['Oportunidades','Território','Contratos','Atas'].includes(tab)&&<><section className="bg-white border rounded-2xl p-4 mb-5"><div className="flex items-center gap-2 text-xs uppercase tracking-wide font-semibold text-[#4b6462] mb-3"><SlidersHorizontal size={15}/> Filtros</div><div className="grid sm:grid-cols-2 xl:grid-cols-4 gap-2"><div className="relative sm:col-span-2"><Search size={17} className="absolute left-3 top-3 text-slate-400"/><input value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')runSearch()}} placeholder="Busca contextual: ex. galpões logísticos em Campinas" className="w-full border rounded-lg py-2.5 pl-10 pr-3 text-sm"/></div><button onClick={runSearch} className="border border-[#24474b] bg-[#24474b] text-white rounded-lg px-4 py-2 text-sm font-medium">Pesquisar</button><select aria-label="Profundidade da busca" value={searchMode} onChange={e=>{setSearchMode(e.target.value as 'quick'|'expanded'|'detailed');setSearchBatch(0)}} className="border rounded-lg px-3 py-2 text-sm"><option value="quick">Rápida · 1 página</option><option value="expanded">Ampliada · até 3 páginas</option><option value="detailed">Detalhada · até 5 páginas</option></select><select value={uf} onChange={e=>{setUf(e.target.value);setPage(1)}} className="border rounded-lg px-3 py-2 text-sm"><option value="">Todo o Brasil</option>{'AC AL AP AM BA CE DF ES GO MA MT MS MG PA PB PR PE PI RJ RN RS RO RR SC SP SE TO'.split(' ').map(x=><option key={x}>{x}</option>)}</select><select value={period} onChange={e=>setPeriodValue(e.target.value)} className="border rounded-lg px-3 py-2 text-sm"><option value="0">Hoje</option><option value="7">Últimos 7 dias</option><option value="30">Últimos 30 dias</option><option value="90">Últimos 90 dias</option><option value="custom">Personalizado</option></select><select value={category} onChange={e=>setCategory(e.target.value)} className="border rounded-lg px-3 py-2 text-sm"><option>Todas</option>{Object.keys(categoryTerms).map(x=><option key={x}>{x}</option>)}<option>Outros</option></select><select value={serviceFilter} onChange={e=>setServiceFilter(e.target.value as Service|'Todas')} className="border rounded-lg px-3 py-2 text-sm"><option value="Todas">Todas as filas</option>{SERVICES.map(s=><option key={s}>{s}</option>)}</select><select value={source} onChange={e=>setSource(e.target.value)} className="border rounded-lg px-3 py-2 text-sm"><option value="Todas">Todas as fontes carregadas</option><option value="PNCP">PNCP · público</option><option value="Obrasgov.br">Obrasgov.br · projetos federais</option><option value="Transferegov.br · Parcerias">Transferegov.br · transferências</option><option value="GDELT">GDELT · notícias</option><option value="OpenStreetMap">OpenStreetMap · edifícios/estabelecimentos</option></select>{source==='OpenStreetMap'&&<select aria-label="Categoria territorial OSM" value={osmCategory} onChange={e=>setOsmCategory(e.target.value)} className="border rounded-lg px-3 py-2 text-sm"><option value="all">Todas as categorias OSM</option><option value="residential">Condomínios / residencial</option><option value="commercial">Comercial / escritórios</option><option value="logistics">Galpões / logística</option><option value="industrial">Industrial</option><option value="healthcare">Hospitais / saúde</option><option value="education">Escolas / educação</option><option value="retail">Lojas / varejo</option><option value="hospitality">Hotéis / restaurantes</option><option value="assembly">Locais de reunião</option><option value="services">Academias / serviços</option><option value="construction">Construção mapeada</option></select>}<><input list="accert-municipalities" value={cityQuery} onChange={e=>setCityQuery(e.target.value)} placeholder="Município (IBGE)" className="border rounded-lg px-3 py-2 text-sm"/><datalist id="accert-municipalities">{municipalities.map(m=><option key={m.code} value={m.name} label={`${m.uf} · código IBGE ${m.code}`}/>)}</datalist></><select value={evidenceFilter} onChange={e=>setEvidenceFilter(e.target.value)} className="border rounded-lg px-3 py-2 text-sm"><option>Todas</option><option>Necessidade comprovada por evidência</option><option>Oportunidade provável</option><option>Oportunidade exploratória</option><option value="A">Classe A · Projeto documentado</option><option value="B">Classe B · Contratação/demanda</option><option value="C">Classe C · Estabelecimento potencial</option><option value="D">Classe D · Sinal indireto</option></select><select value={sort} onChange={e=>setSort(e.target.value)} className="border rounded-lg px-3 py-2 text-sm"><option value="priority">Maior prioridade comercial</option><option value="newest">Mais recentes</option><option value="oldest">Mais antigos</option></select><button onClick={()=>load(1)} className="bg-[#163b3e] text-white rounded-lg px-5 py-2.5 text-sm flex gap-2 items-center justify-center"><Search size={15}/> Consultar</button><button onClick={clearFilters} className="border rounded-lg text-sm px-3 py-2">Limpar filtros</button></div>{period==='custom'&&<div className="mt-2 flex gap-2 items-center text-sm"><label>De <input type="date" value={from} max={to} onChange={e=>setFrom(e.target.value)} className="border rounded px-2 py-1"/></label><label>Até <input type="date" value={to} min={from} max={today} onChange={e=>setTo(e.target.value)} className="border rounded px-2 py-1"/></label></div>}{source!=='Todas'&&<div className="mt-3 text-xs">Origem: {source} <button onClick={()=>setSource('Todas')} className="underline">remover</button></div>}{source==='OpenStreetMap'&&<p className="mt-2 text-xs text-amber-800">Pesquisa limitada ao município e UF escolhidos; até 80 elementos. OSM é contexto mapeado, não prova de licença, obra ativa ou necessidade. Use o link de mapa para verificar cada item na fonte.</p>}<details className="mt-4 border-t pt-3"><summary className="text-xs font-semibold cursor-pointer">Preferências de prospecção (guardadas neste navegador)</summary><div className="grid sm:grid-cols-2 gap-3 mt-3"><label className="text-xs">Região prioritária — cidade ou UF<input value={preferences.region} onChange={e=>updatePreferences({...preferences,region:e.target.value})} placeholder="Ex.: Campinas ou SP" className="block border rounded px-2 py-2 w-full mt-1"/></label><fieldset className="text-xs"><legend>Serviços prioritários</legend>{SERVICES.map(s=><label key={s} className="flex gap-2 items-center mt-1"><input type="checkbox" checked={preferences.services.includes(s)} onChange={e=>updatePreferences({...preferences,services:e.target.checked?[...preferences.services,s]:preferences.services.filter(x=>x!==s)})}/>{s}</label>)}</fieldset><fieldset className="text-xs sm:col-span-2"><legend>Segmentos prioritários (nenhum selecionado = todos)</legend><div className="flex flex-wrap gap-3">{['Indústrias','Galpões e logística','Comércio e edifícios','Hospitais e clínicas','Escolas e instituições','Hotéis','Supermercados','Condomínios','Construção civil','Organização/empreendimento'].map(s=><label key={s} className="flex gap-1 items-center"><input type="checkbox" checked={preferences.segments.includes(s)} onChange={e=>updatePreferences({...preferences,segments:e.target.checked?[...preferences.segments,s]:preferences.segments.filter(x=>x!==s)})}/>{s}</label>)}</div></fieldset></div></details></section><div className="flex justify-between items-center mb-3 text-xs text-slate-500"><span>{loading?'Consultando…':`${filtered.length} exibidos nesta página · ${total} reportados pela fonte`} · página {page}{totalPages?` de ${totalPages}`:''} · filtros de categoria/localidade classificam somente o lote carregado · {tab==='Oportunidades'?`${sources.filter(s=>s.status==='ok'||s.status==='parcial').length}/${sources.filter(s=>s.status!=='não consultada').length} fontes responderam`:(sources[0]?.status||'PNCP')}{updated&&` · consulta ${new Date(updated).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}`}</span><div className="flex gap-2"><select value={size} onChange={e=>{const n=Math.min(Number(e.target.value),kind==='opportunities'?50:100);setSize(n);load(1,n)}} className="border bg-white rounded px-2 py-1"><option value={10}>10 / pág.</option><option value={20}>20 / pág.</option><option value={50}>50 / pág.</option><option value={100}>100 / pág.</option></select><button onClick={exportCSV} disabled={!filtered.length} className="flex gap-1 items-center"><ArrowDownToLine size={14}/> CSV</button><button onClick={exportJSON} disabled={!filtered.length} className="flex gap-1 items-center"><Download size={14}/> JSON</button></div></div></>}
{tab==='Oportunidades'&&sources.length>0&&<section className="bg-white border rounded-xl p-4 mb-4" aria-label="Cobertura das fontes"><div className="flex flex-wrap justify-between gap-2"><b className="text-sm">Cobertura desta consulta</b><span className="text-xs text-amber-800">Amostra paginada · não representa cobertura nacional completa</span></div>{coverageData&&<p className="text-xs text-slate-600 mt-2">{coverageData.recordsFetched} registros recebidos · {coverageData.matchedBeforeDedup} correspondências pré-deduplicação · {coverageData.deduplicated} duplicatas estritas consolidadas{coverageData.evidenceClasses&&` · classes A/B/C/D: ${coverageData.evidenceClasses.A}/${coverageData.evidenceClasses.B}/${coverageData.evidenceClasses.C}/${coverageData.evidenceClasses.D}`}</p>}<div className="grid md:grid-cols-2 gap-2 mt-3">{sources.map((s:any,i:number)=><div key={`${s.id||s.name}-${i}`} className="rounded-lg bg-slate-50 px-3 py-2 text-xs"><div className="flex justify-between gap-2"><b>{s.name}</b><span className={s.status==='ok'?'text-green-800':s.status==='parcial'?'text-amber-800':s.status==='não consultada'?'text-slate-500':'text-red-800'}>{s.status}</span></div><p className="text-slate-600 mt-1">{s.message}{s.durationMs?` · ${s.durationMs} ms`:''}</p></div>)}</div></section>}{error&&<div className="bg-amber-50 border border-amber-200 text-amber-900 rounded-xl p-4 mb-4 flex gap-3 text-sm"><TriangleAlert size={18}/>{error}</div>}
{['Oportunidades','Território','Contratos','Atas'].includes(tab)&&<>{loading?<div className="animate-pulse h-40 bg-white rounded-xl"/>:!filtered.length?<div className="bg-white border rounded-2xl py-14 text-center"><FileSearch className="mx-auto text-slate-300" size={32}/><h3 className="font-semibold mt-3">Nenhum registro encontrado</h3><p className="text-sm text-slate-500 mt-1">Confirme filtros ou tente atualizar.</p><button onClick={()=>load(1)} className="mt-4 text-sm text-teal-800">Atualizar</button></div>:<div className="space-y-3">{filtered.map((item,i)=><article key={`${item.origin}-${item.id}-${i}`} className="bg-white border rounded-2xl p-5"><div className="flex flex-col md:flex-row md:items-start gap-4"><div className="flex-1"><div className="flex gap-2 mb-3"><span className="bg-[#e7f1d9] text-[#4a663d] text-[10px] uppercase font-bold rounded-full px-2.5 py-1">{item.status||item.type}</span><span className="text-[10px] text-slate-400">{item.origins?.length?item.origins.join(' · '):item.origin}</span>{item.evidenceClass&&<span title={item.evidenceClass==='A'?'Projeto registrado em fonte pública; não garante execução':item.evidenceClass==='B'?'Demanda/contratação pública registrada':item.evidenceClass==='C'?'Estabelecimento mapeado; não é obra confirmada':'Sinal indireto ou notícia'} className="text-[10px] bg-slate-100 rounded-full px-2 py-1">Classe {item.evidenceClass}</span>}</div><h2 className="font-semibold text-[#18393c]">{item.title}</h2>{(item.searchEvidence?.length||0)>0&&<p className="mt-2 text-xs text-teal-900">Relevância da busca ({item.searchRelevance}/100): {(item.searchEvidence||[]).join(' · ')}</p>}<div className="flex flex-wrap gap-5 text-xs text-slate-500 mt-3"><span className="flex gap-1"><Building2 size={14}/>{item.buyer||'Órgão não informado'}</span>{(item.city||item.state)&&<span className="flex gap-1"><MapPin size={14}/>{[item.city,item.state].filter(Boolean).join(', ')}</span>}<span className="flex gap-1"><CalendarDays size={14}/>{item.type==='ata'?'Assinatura':'Publicação'} {date(item.published)}</span></div>{item.address&&<p className="text-xs text-slate-600 mt-2">Endereço indicado na fonte: {item.address}</p>}{item.description&&<p className="text-xs text-slate-600 mt-2">{item.description}</p>}{Number.isFinite(item.latitude)&&Number.isFinite(item.longitude)&&<a className="inline-block text-xs text-teal-800 underline mt-2" target="_blank" rel="noreferrer" href={`https://www.openstreetmap.org/?mlat=${item.latitude}&mlon=${item.longitude}#map=17/${item.latitude}/${item.longitude}`}>Ver coordenada no mapa OpenStreetMap</a>}<div className="mt-3 text-xs">Valor: <b>{currency(item.amount)}</b> · Porte: {item.sizeCategory==='small'?'Pequeno':item.sizeCategory==='medium'?'Médio':item.sizeCategory==='large'?'Grande':'não informado'} · Vigência/fim: {date(item.deadline)}{item.supplier&&<> · Fornecedor: <b>{item.supplier}</b>{item.supplierCnpj&&` (${item.supplierCnpj})`}</>}{item.processNumber&&<> · Processo: {item.processNumber}</>}{item.recordNumber&&<> · Número: {item.recordNumber}</>}</div>{item.evidence?.length?<details className="mt-3"><summary className="text-xs cursor-pointer">Evidências da prioridade <ChevronDown size={12} className="inline"/></summary><ul className="text-xs list-disc pl-5 mt-2">{item.evidence.map((x,i)=><li key={i}>{x}</li>)}</ul></details>:null}{(item.sourceRecords?.length||0)>0&&<details className="mt-2"><summary className="text-xs cursor-pointer">Procedência original ({(item.sourceRecords||[]).length})</summary><ul className="text-xs list-disc pl-5 mt-2">{(item.sourceRecords||[]).map((r,i)=><li key={`${r.source}-${r.id}-${i}`}><a href={r.url} target="_blank" rel="noreferrer" className="underline">{r.source} · {r.id}</a></li>)}</ul></details>}{(()=>{const c=classifyLead(item,preferences.region);const tracking=leadState(item);return <div className="mt-4 border-t pt-3 text-sm"><div className="flex flex-wrap gap-2 items-center"><b className="text-[#254f49]">Fila comercial:</b>{c.services.length?c.services.map(s=><span key={s} className="bg-[#edf4e4] text-[#405f3f] rounded px-2 py-1 text-[11px]">{s}</span>):<span className="text-xs text-slate-500">sem associação específica ainda</span>}<span className="ml-auto text-[11px] border rounded-full px-2 py-1">{c.level}</span><span className="text-[11px] font-semibold text-[#264f47]">Prioridade estimada {c.priority}/100</span></div><div className="text-xs text-slate-600 mt-2"><b>Segmento estimado:</b> {c.segment} · <b>Confiança da correspondência:</b> {c.evidenceConfidence}</div><p className="text-xs text-slate-600 mt-1">{c.summary}</p><p className="text-xs text-slate-600 mt-1"><b>Próxima ação:</b> {recommendedAction(c.level)}</p><details className="mt-2"><summary className="text-xs cursor-pointer text-teal-800">Sugestão de abordagem (revisar antes de enviar)</summary><p className="mt-2 bg-slate-50 rounded p-3 text-xs leading-relaxed">{outreach(item)}</p><button onClick={()=>navigator.clipboard?.writeText(outreach(item))} className="mt-1 text-xs underline">Copiar texto</button></details><div className="flex flex-wrap gap-2 items-center mt-3"><label className="text-[11px] text-slate-500">Etapa comercial local</label><select value={tracking.stage} onChange={e=>markLead(item,{stage:e.target.value as PipelineStage})} className="border rounded px-2 py-1 text-xs">{PIPELINE_STAGES.map(s=><option key={s}>{s}</option>)}</select><span className="text-[10px] text-slate-400">Só neste navegador · atualizado {tracking.updatedAt?date(tracking.updatedAt):'ainda não'}</span></div><details className="mt-2"><summary className="text-xs cursor-pointer">Notas e próxima ação (armazenamento local)</summary><label className="block mt-2 text-xs">Notas<textarea value={tracking.notes} maxLength={1000} onChange={e=>markLead(item,{notes:e.target.value})} className="block border rounded w-full p-2 mt-1" rows={2} placeholder="Anotações internas para este navegador"/></label><label className="block mt-2 text-xs">Próxima ação<input value={tracking.nextAction} maxLength={250} onChange={e=>markLead(item,{nextAction:e.target.value})} className="block border rounded w-full p-2 mt-1" placeholder="Ex.: verificar fase da obra antes de contatar"/></label></details></div>})()}</div><div className="flex items-center gap-2"><button title="Favoritar" onClick={()=>toggleSave(item)} className="p-2 rounded border">{saved.some(x=>x.id===item.id&&x.origin===item.origin)?<Check size={16}/>:<Bookmark size={16}/>}</button><a href={item.url} target="_blank" rel="noopener noreferrer" className="text-xs bg-[#173d3e] text-white rounded-lg px-3 py-2 flex items-center gap-1">Ver fonte <ExternalLink size={13}/></a></div></div></article>)}</div>}<div className="flex justify-center gap-3 my-5"><button disabled={page<=1||loading} onClick={()=>load(page-1)} className="border rounded px-4 py-2 disabled:opacity-40">← Anterior</button><span className="px-3 py-2 text-sm">Página {page}{totalPages?` / ${totalPages}`:''}</span><button disabled={loading||data.length<size||(totalPages>0&&page>=totalPages)} onClick={()=>load(page+1)} className="border rounded px-4 py-2 disabled:opacity-40">Próxima →</button>{q&&moreAvailable&&<button disabled={loading} onClick={()=>{const next=searchBatch+1;setPage(1);load(1,size,next)}} className="border border-teal-700 text-teal-900 rounded px-4 py-2 disabled:opacity-40">Ampliar busca na fonte</button>}</div></>}
{tab==='Notícias'&&<><div className="bg-white border rounded-2xl p-4 mb-4"><p className="text-xs text-slate-500 mb-2">GDELT DOC API · notícias são sinais, não comprovação de contratação.</p><div className="flex gap-2"><input value={newsQuery} onChange={e=>setNewsQuery(e.target.value)} placeholder="Palavra-chave (ex.: sprinklers, galpão logístico)" className="border rounded-lg px-3 py-2 flex-1"/><button onClick={doNews} className="bg-[#163b3e] text-white px-4 rounded-lg">Pesquisar</button></div></div>{newsError&&<p className="text-red-600 text-sm">{newsError}</p>}<div className="space-y-3">{newsSorted.map(n=><article key={n.url} className="bg-white border rounded-xl p-5"><div className="text-xs text-slate-500">{n.domain} · {date(n.published)} · {n.potential} relevância potencial</div><h2 className="font-semibold mt-2">{n.title}</h2><p className="text-xs text-slate-600 mt-2">Sinal de notícia — confirme qual organização/empreendimento é mencionado, localidade e fase do projeto na publicação. A matéria não comprova compra, irregularidade ou necessidade de AVCB.</p><p className="text-xs mt-1">Recomendação: validar o contexto e a empresa citada antes de inserir na prospecção. Não são inferidos contatos.</p><details className="mt-2"><summary className="text-xs cursor-pointer text-teal-800">Abordagem exploratória (personalize após verificar)</summary><p className="text-xs bg-slate-50 rounded p-3 mt-2">“Olá, somos a Accert Engenharia. Encontramos a publicação sobre este empreendimento e gostaríamos de entender a fase do projeto e se há interesse em conversar sobre prevenção e segurança contra incêndio. Não presumimos uma necessidade específica.”</p></details><a href={n.url} target="_blank" rel="noopener noreferrer" className="text-xs text-teal-800 underline mt-2 inline-block">Abrir publicação original <ExternalLink size={12} className="inline"/></a></article>)}</div></>}
{tab==='Compras.gov.br'&&<section className="bg-white border rounded-2xl p-6 max-w-3xl"><h2 className="font-semibold">Referências de preços praticados</h2><p className="text-sm text-slate-500 my-2">API oficial do Compras.gov.br exige código CATMAT/CATSER; não oferece busca textual livre neste endpoint.</p><div className="grid sm:grid-cols-3 gap-2"><select value={priceType} onChange={e=>setPriceType(e.target.value)} className="border rounded px-3"><option value="material">Material (CATMAT)</option><option value="servico">Serviço (CATSER)</option></select><input value={priceCode} onChange={e=>setPriceCode(e.target.value)} placeholder="Código de catálogo" className="border rounded px-3 py-2"/><button onClick={lookupPrices} className="bg-[#163b3e] text-white rounded px-4">Consultar preços</button></div>{priceError&&<p className="text-sm text-red-600 mt-3">{priceError}</p>}<div className="mt-4 space-y-2">{prices.map((x,i)=><div key={i} className="border rounded-lg p-3 text-sm"><b>{x.title}</b> · {currency(x.amount)} <span className="text-xs text-slate-500">{date(x.published)} · {x.buyer}</span></div>)}</div></section>}
{tab==='Empresas'&&<section className="bg-white border rounded-2xl p-6 max-w-3xl"><h2 className="font-semibold text-lg">Consulta cadastral por CNPJ</h2><p className="text-sm text-slate-500 my-3">Consulta externa à BrasilAPI por CNPJ, mesmo quando ainda não há registro local. A cobertura depende da fonte; não equivale a confirmação oficial em tempo real.</p><form onSubmit={e=>{e.preventDefault();lookupCompany()}} className="flex flex-col sm:flex-row gap-2"><label className="sr-only" htmlFor="company-cnpj">CNPJ</label><input id="company-cnpj" inputMode="text" autoComplete="off" value={company} onChange={e=>setCompany(formatCnpj(e.target.value))} placeholder="00.000.000/0000-00 ou alfanumérico" className="flex-1 border rounded-lg px-3 py-2.5"/><button disabled={companyLoading} className="bg-[#173c3e] text-white rounded-lg px-5 py-2.5 disabled:opacity-60">{companyLoading?'Consultando…':'Consultar'}</button></form>{companyError&&<p role="status" className="text-sm text-amber-800 mt-4">{companyError}</p>}{companySources.length>0&&<div className="mt-4 rounded-lg border p-3"><b className="text-xs">Fontes consultadas</b>{companySources.map((s,i)=><p key={`${s.name}-${i}`} className="text-xs text-slate-600 mt-1">{s.name}: {s.status} · {s.message}{s.durationMs?` · ${s.durationMs} ms`:''}{s.observedAt?` · ${new Date(s.observedAt).toLocaleString('pt-BR')}`:''}</p>)}</div>}{companyData&&<div className="mt-5 space-y-4"><header className="rounded-xl bg-[#edf4e4] p-4"><div className="flex flex-wrap justify-between gap-2"><div><h3 className="font-semibold text-lg">{companyData.legalName||'Razão social não informada pela fonte'}</h3><p className="text-sm text-slate-600">{companyData.tradeName||'Nome fantasia não informado'} · CNPJ {formatCnpj(companyData.cnpj)}</p></div><button onClick={()=>lookupCompany(true)} disabled={companyLoading} className="border rounded-lg px-3 py-2 text-sm bg-white disabled:opacity-50">Atualizar dados</button></div><p className="text-xs text-slate-600 mt-3">{companyData.establishmentType||'Tipo de estabelecimento não informado'} · Situação: {companyData.registration.label||'Não informada pela fonte'} · consultado {companySources[0]?.observedAt?new Date(companySources[0].observedAt).toLocaleString('pt-BR'):'agora'}</p><p className="text-xs text-slate-600 mt-1">Dados cadastrais não atestam solvência, aptidão, conformidade ou necessidade de serviços Accert.</p></header><div className="grid md:grid-cols-2 gap-3"><section className="border rounded-xl p-4"><h4 className="font-semibold text-sm">Identificação</h4><dl className="grid grid-cols-[auto_1fr] gap-x-3 gap-y-2 text-xs mt-3"><dt>Data de abertura</dt><dd>{companyData.openedAt||'Não informada pela fonte'}</dd><dt>Natureza jurídica</dt><dd>{companyData.legalNature||'Não informada pela fonte'}</dd><dt>Porte</dt><dd>{companyData.size||'Não informado pela fonte'}</dd><dt>Capital social</dt><dd>{companyData.capitalSocial===null?'Não informado pela fonte':currency(companyData.capitalSocial)}</dd><dt>Estabelecimento</dt><dd>{companyData.establishmentType||'Não informado pela fonte'}</dd><dt>Situação em</dt><dd>{companyData.registration.date||'Data não informada'}</dd><dt>Motivo</dt><dd>{companyData.registration.reason||'Não informado pela fonte'}</dd></dl></section><section className="border rounded-xl p-4"><h4 className="font-semibold text-sm">Endereço e contato</h4><p className="text-xs mt-3">{[companyData.address.streetType,companyData.address.street,companyData.address.number,companyData.address.complement,companyData.address.district,companyData.address.city,companyData.address.state,companyData.address.postalCode].filter(Boolean).join(', ')||'Endereço não informado pela fonte'}</p><p className="text-xs mt-2">Telefone(s): {companyData.contacts.phones.join(' · ')||'Não informado pela fonte'}</p><p className="text-xs mt-2">E-mail: {companyData.contacts.email||'Não informado pela fonte'}</p><p className="text-xs mt-2 text-slate-500">Coordenadas não consultadas. Nenhum contato foi inferido.</p></section></div><section className="border rounded-xl p-4"><h4 className="font-semibold text-sm">Atividades econômicas (CNAE)</h4><ul className="text-xs mt-3 space-y-2"><li><b>Principal:</b> {companyData.activities.primary?[`${companyData.activities.primary.code||''} ${companyData.activities.primary.description||''}`.trim()]:'Não informada pela fonte'}</li>{companyData.activities.secondary.map((a,i)=><li key={`${a.code}-${i}`}><b>Secundária:</b> {`${a.code||''} ${a.description||''}`.trim()}</li>)}</ul><p className="text-xs text-slate-500 mt-3">CNAE descreve atividade cadastral; sozinho não confirma compatibilidade, obra ou necessidade comercial.</p></section><div className="grid md:grid-cols-2 gap-3"><section className="border rounded-xl p-4"><h4 className="font-semibold text-sm">Enquadramento</h4><p className="text-xs mt-3">Simples Nacional: {companyData.tax.simples===null?'Não informado':companyData.tax.simples?'Sim':'Não'}{companyData.tax.simplesSince?` · desde ${companyData.tax.simplesSince}`:''}{companyData.tax.simplesUntil?` · até ${companyData.tax.simplesUntil}`:''}</p><p className="text-xs mt-2">MEI: {companyData.tax.mei===null?'Não informado':companyData.tax.mei?'Sim':'Não'}{companyData.tax.meiSince?` · desde ${companyData.tax.meiSince}`:''}{companyData.tax.meiUntil?` · até ${companyData.tax.meiUntil}`:''}</p></section><section className="border rounded-xl p-4"><h4 className="font-semibold text-sm">Sócios e administradores retornados</h4>{companyData.partners.length?<ul className="text-xs mt-3 space-y-2">{companyData.partners.map((p,i)=><li key={`${p.name}-${i}`}>{p.name||'Nome não informado'} · {p.qualification||'qualificação não informada'} · entrada: {p.since||'não informada'}{p.ageRange?` · ${p.ageRange}`:''}</li>)}</ul>:<p className="text-xs text-slate-500 mt-3">A fonte não retornou quadro societário.</p>}</section></div><p className="text-xs text-slate-500">Origem de todos os campos exibidos: BrasilAPI / CNPJ. Data da consulta exibida acima; data de referência varia por campo. Fonte pode mascarar dados pessoais. Consulte a origem antes de tomar decisões.</p></div>}{companyHistory.length>0&&<details className="mt-5 border-t pt-3"><summary className="text-sm font-medium cursor-pointer">Histórico desta sessão ({companyHistory.length})</summary><ul className="text-xs mt-2 space-y-2">{companyHistory.map((h,i)=><li key={`${h.cnpj}-${i}`} className="flex flex-wrap justify-between gap-2"><button onClick={()=>setCompany(formatCnpj(h.cnpj))} className="underline text-left">{formatCnpj(h.cnpj)} · {h.name}</button><span>{h.status} · {new Date(h.checkedAt).toLocaleString('pt-BR')}</span></li>)}</ul><p className="text-[11px] text-slate-500 mt-2">Histórico apenas nesta sessão; não é salvo no servidor nem sincronizado.</p></details>}</section>}
{tab==='Salvos'&&<><div className="bg-white border rounded-xl p-4 mb-4 flex flex-wrap gap-2 items-center"><button onClick={exportFavorites} className="border rounded px-3 py-2 text-sm flex gap-2"><Download size={15}/> Exportar workspace JSON</button><button onClick={()=>fileRef.current?.click()} className="border rounded px-3 py-2 text-sm flex gap-2"><Upload size={15}/> Importar e mesclar JSON</button><input ref={fileRef} type="file" accept="application/json,.json" className="hidden" onChange={e=>importFavorites(e.target.files?.[0])}/><span className="text-xs text-slate-500">Local neste navegador. JSON permite transferência manual.</span></div>{saved.map(x=><article key={`${x.origin}:${x.id}`} className="bg-white border rounded-xl p-4 mb-3 flex justify-between gap-2"><div><span className="text-[10px] text-slate-500">{x.origin}</span><h3 className="font-semibold">{x.title}</h3><p className="text-xs text-slate-500">{x.buyer}</p></div><div className="flex gap-2 items-center"><a href={x.url} target="_blank" rel="noopener noreferrer" aria-label="Abrir origem"><ExternalLink size={16}/></a><button onClick={()=>persist(saved.filter(y=>y.id!==x.id||y.origin!==x.origin))} title="Remover"><Trash2 size={16}/></button></div></article>)}{!saved.length&&<div className="bg-white border rounded-xl p-10 text-center text-slate-500">Você ainda não salvou registros.</div>}</>}
<footer className="border-t mt-8 py-4 text-[11px] text-slate-400 flex justify-between"><span>ACCERT INTELLIGENCE · Dados de terceiros sujeitos a atualização</span><span>Rate limit local é best-effort; produção precisa de WAF/distribuído.</span></footer></div></main></div>}
